//! Per-Plugin Typed gRPC Services - Frozen at D-Bus Object Creation
//!
//! This module generates typed gRPC services from plugin schemas at the moment
//! a D-Bus object is created. The services are "frozen" - they reflect the
//! schema exactly as it existed at creation time and never change.
//!
//! Architecture:
//! ```text
//!     SchemaEngine ──► PluginSchema ──► PerPluginGrpcService (frozen)
//!           │                               │
//!           │                               ▼
//!           │                    gRPC Reflection (typed)
//!           │                               │
//!           ▼                               ▼
//!      /dev/shm/live-schema.json    Dynamic gRPC dispatch
//! ```
//!
//! Each plugin gets its own gRPC service with methods matching exactly the
//! D-Bus methods from the schema. The reflection service shows the exact
//! typed interface.

use std::collections::HashMap;
use std::sync::Arc;

use op_state_store::{MethodDecl, PluginSchema};
use tokio::sync::{broadcast, RwLock};
use tonic::{Request, Response, Status};

/// Manages frozen per-plugin gRPC services.
///
/// Once a plugin's D-Bus object is created, its gRPC service is generated
/// and frozen - it will never change, even if the schema updates. This ensures
/// stable API contracts for clients.
pub struct PluginGrpcServices {
    /// plugin_id -> ServiceRegistry
    services: Arc<RwLock<HashMap<String, ServiceRegistry>>>,
    /// Broadcast channel for service lifecycle events
    lifecycle_tx: broadcast::Sender<ServiceLifecycleEvent>,
}

/// A frozen gRPC service registry for a single plugin.
#[derive(Clone)]
pub struct ServiceRegistry {
    pub plugin_id: String,
    pub schema_version: String,
    pub methods: HashMap<String, MethodHandler>,
    pub generated_at: std::time::Instant,
}

/// Handler for a single method.
pub struct MethodHandler {
    pub name: String,
    pub input_schema: simd_json::OwnedValue,
    pub output_schema: simd_json::OwnedValue,
    pub required_capability: Option<String>,
    pub handler: Arc<dyn Fn(simd_json::OwnedValue) -> Result<simd_json::OwnedValue, anyhow::Error> + Send + Sync>,
}

/// Events emitted when services are created or removed.
#[derive(Clone, Debug)]
pub enum ServiceLifecycleEvent {
    Created { plugin_id: String, method_count: usize },
    Removed { plugin_id: String },
}

impl PluginGrpcServices {
    /// Create a new registry.
    pub fn new() -> Arc<Self> {
        let (lifecycle_tx, _) = broadcast::channel(64);
        Arc::new(Self {
            services: Arc::new(RwLock::new(HashMap::new())),
            lifecycle_tx,
        })
    }

    /// Get the lifecycle event receiver.
    pub fn lifecycle_rx(&self) -> broadcast::Receiver<ServiceLifecycleEvent> {
        self.lifecycle_tx.subscribe()
    }

    /// Create a frozen gRPC service from a plugin schema.
    ///
    /// This is called at D-Bus object creation time. The resulting service
    /// is frozen - it reflects the schema exactly as it was at this moment.
    pub async fn create_frozen_service(
        &self,
        plugin_id: String,
        schema: &PluginSchema,
    ) -> Result<ServiceRegistry, anyhow::Error> {
        let methods = self.generate_method_handlers(schema)?;

        let registry = ServiceRegistry {
            plugin_id: plugin_id.clone(),
            schema_version: schema.version.clone(),
            methods,
            generated_at: std::time::Instant::now(),
        };

        let method_count = registry.methods.len();

        // Store the registry
        let mut services = self.services.write().await;
        services.insert(plugin_id.clone(), registry.clone());

        // Emit lifecycle event
        let _ = self.lifecycle_tx.send(ServiceLifecycleEvent::Created {
            plugin_id: plugin_id.clone(),
            method_count,
        });

        Ok(registry)
    }

    /// Generate method handlers from a plugin schema.
    fn generate_method_handlers(
        &self,
        schema: &PluginSchema,
    ) -> Result<HashMap<String, MethodHandler>, anyhow::Error> {
        let mut handlers = HashMap::new();

        for (method_name, method_decl) in &schema.methods {
            let handler = MethodHandler {
                name: method_name.clone(),
                input_schema: method_decl.args.clone(),
                output_schema: method_decl.output.clone().unwrap_or(simd_json::json!({})),
                required_capability: method_decl.required_capability.clone(),
                handler: Arc::new(move |_input| {
                    // Default handler - actual implementation comes from MutationEngine
                    Ok(simd_json::json!({
                        "status": "ok",
                        "method": method_name,
                    }))
                }),
            };

            handlers.insert(method_name.clone(), handler);
        }

        Ok(handlers)
    }

    /// Get a service registry by plugin_id.
    pub async fn get_service(&self, plugin_id: &str) -> Option<ServiceRegistry> {
        let services = self.services.read().await;
        services.get(plugin_id).cloned()
    }

    /// List all registered plugin IDs.
    pub async fn list_plugins(&self) -> Vec<String> {
        let services = self.services.read().await;
        services.keys().cloned().collect()
    }

    /// Remove a frozen service when its D-Bus object is removed.
    pub async fn remove_service(&self, plugin_id: &str) -> bool {
        let mut services = self.services.write().await;
        if services.remove(plugin_id).is_some() {
            let _ = self.lifecycle_tx.send(ServiceLifecycleEvent::Removed {
                plugin_id: plugin_id.to_string(),
            });
            true
        } else {
            false
        }
    }
}

/// Default implementation for testing.
impl Default for PluginGrpcServices {
    fn default() -> Self {
        Self::new()
    }
}

// =============================================================================
// Dynamic gRPC Service Implementation
// =============================================================================

/// Dynamic service that dispatches to frozen per-plugin handlers.
///
/// This implements the `tonic::Service` trait to enable dynamic routing
/// based on the service name (which corresponds to plugin_id).
pub struct DynamicPluginService {
    services: Arc<PluginGrpcServices>,
}

impl DynamicPluginService {
    pub fn new(services: Arc<PluginGrpcServices>) -> Self {
        Self { services }
    }
}

impl tonic::Service<tonic::Request<prost::bytes::Bytes>> for DynamicPluginService {
    type Response = tonic::Response<prost::bytes::Bytes>;
    type Error = Status;
    type Future = futures::future::Ready<Result<Self::Response, Self::Error>>;

    fn poll_ready(
        &mut self,
        _cx: &mut std::task::Context<'_>,
    ) -> std::task::Poll<Result<(), Self::Error>> {
        std::task::Poll::Ready(Ok(()))
    }

    fn call(&mut self, request: tonic::Request<prost::bytes::Bytes>) -> Self::Future {
        // Extract service name from the request path
        let path = request.uri().path();

        // Parse the service name from the path (e.g., /operation.plugin.zeroclaw.GrpcService/Method)
        let service_name = path
            .split('/')
            .nth(1)
            .and_then(|s| s.split('.').last())
            .unwrap_or("unknown");

        // For now, return unimplemented - actual implementation requires
        // more complex request parsing and handler dispatch
        futures::future::ready(Err(Status::unimplemented(format!(
            "Dynamic service call to {} not yet implemented",
            service_name
        ))))
    }
}

// =============================================================================
// Reflection Support
// =============================================================================

/// Generate a FileDescriptorSet for all frozen plugin services.
///
/// This enables gRPC reflection to show the exact typed methods for each
/// plugin service.
pub fn generate_plugin_file_descriptor(
    plugin_id: &str,
    schema: &PluginSchema,
) -> Vec<u8> {
    let mut proto = String::new();

    // Generate proto syntax
    proto.push_str("syntax = \"proto3\";\n\n");
    proto.push_str(&format!("package operation.plugin.{};\n\n", plugin_id));
    proto.push_str("import \"google/protobuf/descriptor.proto\";\n");
    proto.push_str("import \"google/protobuf/struct.proto\";\n\n");

    // Generate message types for method inputs/outputs
    for (method_name, method_decl) in &schema.methods {
        let input_name = format!("{}Input", method_name);
        let output_name = format!("{}Output", method_name);

        // Generate input message
        proto.push_str(&format!("message {} {{\n", input_name));
        proto.push_str("  google.protobuf.Struct args = 1;\n");
        proto.push_str("}\n\n");

        // Generate output message
        proto.push_str(&format!("message {} {{\n", output_name));
        proto.push_str("  google.protobuf.Struct result = 1;\n");
        proto.push_str("}\n\n");
    }

    // Generate service definition
    let service_name = to_service_name(plugin_id);
    proto.push_str(&format!("service {} {{\n", service_name));

    for (method_name, _method_decl) in &schema.methods {
        let input_name = format!("{}Input", method_name);
        let output_name = format!("{}Output", method_name);

        proto.push_str(&format!(
            "  rpc {}({}) returns ({});\n",
            method_name, input_name, output_name
        ));
    }

    proto.push_str("}\n");

    // Compile the proto (in practice this would use tonic_build)
    // For now, return empty bytes - real implementation would compile
    Vec::new()
}

fn to_service_name(plugin_id: &str) -> String {
    let parts: Vec<&str> = plugin_id.split('.').collect();
    parts
        .iter()
        .map(|p| {
            let mut chars = p.chars();
            match chars.next() {
                None => String::new(),
                Some(c) => c.to_uppercase().chain(chars).collect(),
            }
        })
        .collect::<Vec<_>>()
        .join("")
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_service_name_conversion() {
        assert_eq!(to_service_name("zeroclaw"), "Zeroclaw");
        assert_eq!(to_service_name("unix_socket"), "UnixSocket");
        assert_eq!(to_service_name("op.zeroclaw"), "OpZeroclaw");
    }

    #[tokio::test]
    async fn test_create_frozen_service() {
        let services = PluginGrpcServices::new();

        let schema = op_state_store::PluginSchema::builder("test_plugin")
            .version("1.0.0")
            .description("Test plugin")
            .method("TestMethod", op_state_store::MethodDecl {
                name: "TestMethod".to_string(),
                args: simd_json::json!({"type": "object"}),
                output: Some(simd_json::json!({"type": "object"})),
                required_capability: None,
                description: "A test method".to_string(),
                atomic_operations: false,
                subid: "exp.service.test.method@v1".to_string(),
            })
            .build();

        let registry = services
            .create_frozen_service("test_plugin".to_string(), &schema)
            .await
            .unwrap();

        assert_eq!(registry.plugin_id, "test_plugin");
        assert_eq!(registry.schema_version, "1.0.0");
        assert_eq!(registry.methods.len(), 1);
        assert!(registry.methods.contains_key("TestMethod"));
    }

    #[tokio::test]
    async fn test_list_plugins() {
        let services = PluginGrpcServices::new();

        let schema = op_state_store::PluginSchema::builder("plugin1")
            .version("1.0.0")
            .build();

        services
            .create_frozen_service("plugin1".to_string(), &schema)
            .await
            .unwrap();

        let plugins = services.list_plugins().await;
        assert_eq!(plugins, vec!["plugin1"]);
    }

    #[tokio::test]
    async fn test_remove_service() {
        let services = PluginGrpcServices::new();

        let schema = op_state_store::PluginSchema::builder("plugin1")
            .version("1.0.0")
            .build();

        services
            .create_frozen_service("plugin1".to_string(), &schema)
            .await
            .unwrap();

        let removed = services.remove_service("plugin1").await;
        assert!(removed);

        let plugins = services.list_plugins().await;
        assert!(plugins.is_empty());
    }
}

