//! Per-Plugin gRPC Reflection Integration
//!
//! This module integrates per-plugin typed gRPC services with reflection.
//! When a D-Bus object is created for a plugin, its gRPC service is generated
//! and registered with the reflection service so clients can discover the exact
//! typed methods.

use std::collections::HashMap;
use std::sync::Arc;

use op_state_store::PluginSchema;
use tokio::sync::RwLock;

/// Per-plugin service configuration for reflection.
#[derive(Clone)]
pub struct PerPluginReflectionConfig {
    /// Whether to enable per-plugin reflection
    pub enabled: bool,
    /// Base package name for plugin services
    pub base_package: String,
}

impl Default for PerPluginReflectionConfig {
    fn default() -> Self {
        Self {
            enabled: true,
            base_package: "operation.plugin".to_string(),
        }
    }
}

/// Manages per-plugin gRPC service metadata for reflection.
///
/// This keeps track of which plugins have been registered for gRPC and their
/// method counts, so the reflection service can advertise them correctly.
#[derive(Default)]
pub struct PerPluginReflectionRegistry {
    /// plugin_id -> PluginServiceMeta
    services: Arc<RwLock<HashMap<String, PluginServiceMeta>>>,
}

/// Metadata about a registered plugin gRPC service.
#[derive(Clone, Debug)]
pub struct PluginServiceMeta {
    pub plugin_id: String,
    pub service_name: String,
    pub method_count: usize,
    pub schema_version: String,
    pub registered_at: std::time::Instant,
}

impl PerPluginReflectionRegistry {
    /// Create a new registry.
    pub fn new() -> Self {
        Self::default()
    }

    /// Register a plugin's gRPC service metadata.
    pub async fn register(
        &self,
        plugin_id: String,
        schema: &PluginSchema,
    ) -> PluginServiceMeta {
        let service_name = to_grpc_service_name(&plugin_id);
        let method_count = schema.methods.len();

        let meta = PluginServiceMeta {
            plugin_id: plugin_id.clone(),
            service_name,
            method_count,
            schema_version: schema.version.clone(),
            registered_at: std::time::Instant::now(),
        };

        let mut services = self.services.write().await;
        services.insert(plugin_id, meta.clone());

        meta
    }

    /// Get metadata for a plugin.
    pub async fn get(&self, plugin_id: &str) -> Option<PluginServiceMeta> {
        let services = self.services.read().await;
        services.get(plugin_id).cloned()
    }

    /// List all registered plugin services.
    pub async fn list(&self) -> Vec<PluginServiceMeta> {
        let services = self.services.read().await;
        services.values().cloned().collect()
    }

    /// Unregister a plugin's gRPC service.
    pub async fn unregister(&self, plugin_id: &str) -> bool {
        let mut services = self.services.write().await;
        services.remove(plugin_id).is_some()
    }

    /// Generate reflection file descriptor bytes for all registered plugins.
    ///
    /// This creates a combined FileDescriptorSet that can be registered with
    /// tonic-reflection to expose all per-plugin services.
    pub fn generate_file_descriptor_set(&self, schemas: &HashMap<String, PluginSchema>) -> Vec<u8> {
        // In a full implementation, this would compile protobuf for each plugin
        // and combine them into a single FileDescriptorSet.
        // For now, this is a placeholder that returns empty bytes.

        // The actual implementation would:
        // 1. For each plugin in schemas, generate proto definition
        // 2. Compile each proto to FileDescriptorProto
        // 3. Combine all into a FileDescriptorSet
        // 4. Return the encoded bytes

        Vec::new()
    }
}

/// Convert a plugin_id to a gRPC service name.
///
/// Examples:
///   - "zeroclaw" -> "ZeroclawService"
///   - "unix_socket" -> "UnixSocketService"
///   - "op.zeroclaw" -> "OpZeroclawService"
pub fn to_grpc_service_name(plugin_id: &str) -> String {
    let parts: Vec<&str> = plugin_id.split('.').collect();
    let name_part = parts.last().unwrap_or(&plugin_id);

    let mut result = String::new();
    let mut capitalize_next = true;

    for c in name_part.chars() {
        if c == '_' || c == '-' {
            capitalize_next = true;
        } else if capitalize_next {
            result.extend(c.to_uppercase());
            capitalize_next = false;
        } else {
            result.push(c);
        }
    }

    format!("{}Service", result)
}

/// Generate protobuf definition for a plugin's gRPC service.
///
/// This creates the proto3 syntax needed to compile a service with methods
/// corresponding to the plugin's D-Bus methods.
pub fn generate_plugin_proto(plugin_id: &str, schema: &PluginSchema) -> String {
    let mut proto = String::new();

    // Header
    proto.push_str("syntax = \"proto3\";\n\n");
    proto.push_str(&format!("package {}.{};\n\n", 
        PerPluginReflectionConfig::default().base_package,
        plugin_id.replace('.', "_")
    ));
    proto.push_str("import \"google/protobuf/descriptor.proto\";\n");
    proto.push_str("import \"google/protobuf/struct.proto\";\n\n");

    // Extend descriptor for custom options
    proto.push_str("extend google.protobuf.MethodOptions {\n");
    proto.push_str("  string plugin_subid = 50000;\n");
    proto.push_str("  string required_capability = 50001;\n");
    proto.push_str("}\n\n");

    // Generate method input/output messages
    for (method_name, method_decl) in &schema.methods {
        let input_name = format!("{}Input", method_name);
        let output_name = format!("{}Output", method_name);

        // Input message
        proto.push_str(&format!("message {} {{\n", input_name));
        proto.push_str("  // Method arguments as JSON structure\n");
        proto.push_str("  google.protobuf.Struct args = 1;\n");
        proto.push_str("}\n\n");

        // Output message
        proto.push_str(&format!("message {} {{\n", output_name));
        proto.push_str("  // Method result as JSON structure\n");
        proto.push_str("  google.protobuf.Struct result = 1;\n");
        proto.push_str("  string error = 2;\n");
        proto.push_str("}\n\n");
    }

    // Generate service definition
    let service_name = to_grpc_service_name(plugin_id);
    proto.push_str(&format!("service {} {{\n", service_name));

    for (method_name, method_decl) in &schema.methods {
        let input_name = format!("{}Input", method_name);
        let output_name = format!("{}Output", method_name);
        let subid = &method_decl.subid;
        let capability = method_decl.required_capability.as_deref().unwrap_or("");

        proto.push_str(&format!(
            "  // subid: {}, capability: {}\n",
            subid, capability
        ));
        proto.push_str(&format!(
            "  rpc {}({}) returns ({});\n",
            method_name, input_name, output_name
        ));
    }

    proto.push_str("}\n");

    proto
}

/// Generate all plugin protos as a combined string.
pub fn generate_all_plugin_protos(schemas: &HashMap<String, PluginSchema>) -> String {
    let mut combined = String::new();

    for (plugin_id, schema) in schemas {
        combined.push_str(&format!(
            "// ================================================\n",
        ));
        combined.push_str(&format!(
            "// Plugin: {} (v{})\n",
            plugin_id, schema.version
        ));
        combined.push_str(&format!(
            "// ================================================\n",
        ));
        combined.push_str("\n");
        combined.push_str(&generate_plugin_proto(plugin_id, schema));
        combined.push_str("\n\n");
    }

    combined
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_service_name_conversion() {
        assert_eq!(to_grpc_service_name("zeroclaw"), "ZeroclawService");
        assert_eq!(to_grpc_service_name("unix_socket"), "UnixSocketService");
        assert_eq!(to_grpc_service_name("op.zeroclaw"), "ZeroclawService");
        assert_eq!(to_grpc_service_name("wireguard-uplink"), "WireguardUplinkService");
    }

    #[tokio::test]
    async fn test_register_and_list() {
        let registry = PerPluginReflectionRegistry::new();

        let schema = PluginSchema::builder("test_plugin")
            .version("1.0.0")
            .method("TestMethod", op_state_store::MethodDecl {
                name: "TestMethod".to_string(),
                args: simd_json::json!({}),
                output: Some(simd_json::json!({})),
                required_capability: None,
                description: "Test".to_string(),
                atomic_operations: false,
                subid: "exp.test".to_string(),
            })
            .build();

        let meta = registry.register("test_plugin".to_string(), &schema).await;

        assert_eq!(meta.plugin_id, "test_plugin");
        assert_eq!(meta.service_name, "TestPluginService");
        assert_eq!(meta.method_count, 1);
        assert_eq!(meta.schema_version, "1.0.0");

        let list = registry.list().await;
        assert_eq!(list.len(), 1);
        assert_eq!(list[0].plugin_id, "test_plugin");
    }

    #[tokio::test]
    async fn test_unregister() {
        let registry = PerPluginReflectionRegistry::new();

        let schema = PluginSchema::builder("test_plugin")
            .version("1.0.0")
            .build();

        registry.register("test_plugin".to_string(), &schema).await;

        let removed = registry.unregister("test_plugin").await;
        assert!(removed);

        let meta = registry.get("test_plugin").await;
        assert!(meta.is_none());
    }

    #[test]
    fn test_generate_proto() {
        let schema = PluginSchema::builder("zeroclaw")
            .version("1.0.0")
            .method("RegisterAgent", op_state_store::MethodDecl {
                name: "RegisterAgent".to_string(),
                args: simd_json::json!({
                    "type": "object",
                    "properties": {
                        "agent_id": {"type": "string"}
                    }
                }),
                output: Some(simd_json::json!({
                    "type": "object",
                    "properties": {
                        "success": {"type": "boolean"}
                    }
                })),
                required_capability: Some("register".to_string()),
                description: "Register an agent".to_string(),
                atomic_operations: false,
                subid: "exp.service.zeroclaw.register-agent@v1".to_string(),
            })
            .build();

        let proto = generate_plugin_proto("zeroclaw", &schema);

        assert!(proto.contains("service ZeroclawService {"));
        assert!(proto.contains("rpc RegisterAgent"));
        assert!(proto.contains("RegisterAgentInput"));
        assert!(proto.contains("RegisterAgentOutput"));
        assert!(proto.contains("subid: exp.service.zeroclaw.register-agent@v1"));
    }
}

