/// Generate a FileDescriptorSet for a single method's gRPC service.
///
/// This enables gRPC reflection to show the exact typed method interface.
pub fn generate_method_file_descriptor(
    plugin_id: &str,
    method_name: &str,
    method_decl: &MethodDecl,
) -> Vec<u8> {
    let mut proto = String::new();

    // Generate proto syntax
    proto.push_str("syntax = \"proto3\";\n\n");
    proto.push_str(&format!(
        "package operation.method.{}.{};\n\n",
        plugin_id.replace('.', "_"),
        method_name
    ));
    proto.push_str("import \"google/protobuf/descriptor.proto\";\n");
    proto.push_str("import \"google/protobuf/struct.proto\";\n\n");

    // Extend descriptor for custom options
    proto.push_str("extend google.protobuf.MethodOptions {\n");
    proto.push_str("  string plugin_subid = 50000;\n");
    proto.push_str("  string required_capability = 50001;\n");
    proto.push_str("}\n\n");

    // Input message
    let input_name = format!("{}Input", method_name);
    proto.push_str(&format!("message {} {{\n", input_name));
    proto.push_str("  google.protobuf.Struct args = 1;\n");
    proto.push_str("}\n\n");

    // Output message
    let output_name = format!("{}Output", method_name);
    proto.push_str(&format!("message {} {{\n", output_name));
    proto.push_str("  google.protobuf.Struct result = 1;\n");
    proto.push_str("  string error = 2;\n");
    proto.push_str("}\n\n");

    // Generate service definition (one service per method)
    let service_name = to_service_name(method_name);
    proto.push_str(&format!("service {} {{\n", service_name));

    let subid = &method_decl.subid;
    let capability = method_decl.required_capability.as_deref().unwrap_or("");

    proto.push_str(&format!(
        "  // subid: {}, capability: {}\n",
        subid, capability
    ));
    proto.push_str(&format!(
        "  rpc {}({}) returns ({});\n",
        method_name, input_name, output_name
    ));

    proto.push_str("}\n");

    // In a full implementation, this would compile the proto to bytes
    // using tonic_build. For now, return empty - the real impl would
    // integrate with tonic_reflection.
    Vec::new()
}

fn to_service_name(method_name: &str) -> String {
    let mut chars = method_name.chars();
    match chars.next() {
        None => String::new(),
        Some(c) => c.to_uppercase().chain(chars).collect(),
    }
}

