        .await
        .map_err(|e| Status::internal(format!("Mail proxy error: {}", e)))?;
        let result: String = proxy
            .call(method, &(args.to_string(),))
            .await
            .map_err(|e| {
                Status::unavailable(format!(
                    "Mail D-Bus service unavailable for '{}': {}",
                    method, e
                ))
            })?;
        Ok(result)
    }
